using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using PeerChatDesktop;
class AdapterTest {
    static void Require(bool condition,string reason){if(!condition)throw new Exception(reason);}
    static void Until(Func<bool> check,Action pump,string label){var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<20000){pump();if(check())return;Thread.Sleep(30);}throw new Exception("Timeout: "+label);}
    static void CopyDirectory(string source,string target){Directory.CreateDirectory(target);foreach(string file in Directory.GetFiles(source))File.Copy(file,Path.Combine(target,Path.GetFileName(file)),true);foreach(string child in Directory.GetDirectories(source))CopyDirectory(child,Path.Combine(target,Path.GetFileName(child)));}
    static void TestLocalSubnetTransition(){
        var subnet14=new[]{new LocalSubnetInterface{Name="Wi-Fi",Address="192.168.1.14",Mask="255.255.255.0"},new LocalSubnetInterface{Name="Broken VPN",IgnoredReason="IPv4 subnet mask unavailable"}};
        var subnet17=new[]{new LocalSubnetInterface{Name="Ethernet",Address="192.168.1.17",Mask="255.255.255.0"}};
        var from14=LocalSubnetClassifier.Evaluate("192.168.1.17",subnet14);var from17=LocalSubnetClassifier.Evaluate("192.168.1.14",subnet17);
        Require(from14.SameSubnet&&from17.SameSubnet,"192.168.1.14/24 and 192.168.1.17/24 were not classified as the same LAN in both directions");Require(from14.Diagnostics.Contains("same_subnet=yes")&&from14.Diagnostics.Contains("ignored=IPv4 subnet mask unavailable"),"Subnet diagnostics did not correlate match and ignored-interface reasons");
        var hotspot=new[]{new LocalSubnetInterface{Name="Phone hotspot",Address="10.211.241.175",Mask="255.255.255.0"}};Require(!LocalSubnetClassifier.Evaluate("192.168.1.17",hotspot).SameSubnet&&LocalSubnetClassifier.Evaluate("10.211.241.200",hotspot).SameSubnet,"Network transition retained the old private LAN or rejected the current hotspot subnet");
    }
    static void TestFriendConversationIdentity(string root){
        string oldPeer=new string('a',64),newPeer=new string('b',64),profileA=Path.Combine(root,"social-A"),profileB=Path.Combine(root,"social-B");
        Func<byte[],byte[]> identity=data=>data;var friend=new DiscoverySearchResult{AccountId=42,Username="Alice",PublicIdentity=oldPeer,Online=false};var index=new FriendConversationIndex(profileA,identity,identity);index.Reconcile(new[]{friend});
        var loaded=new FriendConversationIndex(profileA,identity,identity);Require(loaded.Records.Single().CurrentPeerId==oldPeer,"Friend mapping did not persist in its profile");Require(!new FriendConversationIndex(profileB,identity,identity).Records.Any(),"Friend mapping leaked into another profile");
        var view=new ChatViewModel();bool reused;var conversation=view.BindFriend(42,"Alice",oldPeer,loaded.Records.Single().KnownPeerIds,out reused);Require(!reused&&conversation.ConversationId=="account:42","Stable account conversation was not created");
        view.Apply(new CoreEvent{kind=1,contacts=new[]{new ContactData{peer=oldPeer,name="old",verified=true}}});view.Apply(new CoreEvent{kind=6,peer=oldPeer,messages=new[]{new MessageData{id="old",sender=oldPeer,text="offline",logical=1}}});
        var same=view.BindFriend(42,"Alice Renamed",newPeer,new[]{oldPeer,newPeer},out reused);Require(reused&&Object.ReferenceEquals(conversation,same)&&view.Conversations.Count==1,"Device change created a duplicate conversation");Require(same.Name=="Alice Renamed"&&same.PreviousVerifiedPeerId==oldPeer&&!same.Contact.verified,"Name/device reconciliation bypassed identity verification");
        view.Apply(new CoreEvent{kind=6,peer=newPeer,messages=new[]{new MessageData{id="new",sender=newPeer,text="online",logical=2}}});Require(same.Messages.Count==2&&Object.ReferenceEquals(view.FindByPeer(oldPeer),view.FindByPeer(newPeer)),"Old and new device history did not merge into one social conversation");
        var log=new ConnectionDiagnosticLog(profileA);for(int i=0;i<600;i++)log.Record("tcp",42,"account:42",newPeer,newPeer,"192.0.2.1:7777","discovery","LAN","TCP timeout");Require(new FileInfo(Path.Combine(profileA,"connection.log")).Length<=160000,"Connection log was not bounded");
string peerTwo=new string('c',64),wrongPeer=new string('d',64);var second=view.BindFriend(43,"Bob",peerTwo,new[]{peerTwo},out reused);var tracker=new ConnectionAttemptTracker();tracker.Update(new CoreEvent{expected=newPeer,peer=newPeer,candidate="192.0.2.10:7777",source="Discovery LAN candidate",route="same LAN",attempt=11},same,"Connecting",null,"TCP timeout");tracker.Update(new CoreEvent{expected=peerTwo,peer=peerTwo,candidate="198.51.100.20:8888",source="Server-observed Internet address",route="public fallback",attempt=12},second,"Connecting",null,"Connection refused");Require(tracker.For(same).ExpectedPeer==newPeer&&tracker.For(same).Candidate=="192.0.2.10:7777"&&tracker.For(same).Failure=="TCP timeout","Account A diagnostics were overwritten");Require(tracker.For(second).ExpectedPeer==peerTwo&&tracker.For(second).Candidate=="198.51.100.20:8888"&&tracker.For(second).Failure=="Connection refused","Account B diagnostics were not independently correlated");var winner=new CoreEvent{kind=3,expected=newPeer,peer=newPeer,candidate="203.0.113.8:7777",source="Inbound direct connection",route="incoming authenticated route",detail="inbound",attempt=101};view.Apply(winner);tracker.Update(winner,same,"Ready","Verified","None");var loser=new CoreEvent{kind=8,expected=newPeer,peer=newPeer,candidate="192.168.1.17:7777",source="Saved contact",route="automatic reconnect",detail="outbound",attempt=100,text="TCP connection timeout"};view.Apply(loser);tracker.Update(loser,same,loser.text,null,"TCP timeout");var projected=tracker.For(same);Require(same.Online&&same.ConnectionState=="Ready"&&projected.HasLiveSession&&projected.LiveConnectionId==101&&projected.Candidate=="203.0.113.8:7777"&&projected.LiveDirection=="inbound"&&projected.LatestFailedAttemptId==100&&projected.LatestFailedCandidate=="192.168.1.17:7777","Loser timeout overwrote the authenticated winning session projection");view.Apply(new CoreEvent{kind=4,expected=newPeer,peer=newPeer,attempt=100,text="delayed old-generation timeout"});Require(same.Online,"Old-generation disconnect downgraded the winning session");view.Apply(new CoreEvent{kind=4,expected=newPeer,peer=newPeer,attempt=101,text="remote EOF"});Require(!same.Online,"Winning-session disconnect did not clear connected state");var outboundWinner=new CoreEvent{kind=3,expected=peerTwo,peer=peerTwo,candidate="198.51.100.20:7777",source="Server-observed Internet address",route="public candidate",detail="outbound",attempt=201};view.Apply(outboundWinner);tracker.Update(outboundWinner,second,"Ready","Verified","None");var inboundLoser=new CoreEvent{kind=16,expected=peerTwo,peer=peerTwo,candidate="192.168.1.20:7777",source="Inbound direct connection",route="incoming authenticated route",detail="inbound",attempt=202,text="duplicate connection loser"};view.Apply(inboundLoser);tracker.Update(inboundLoser,second,null,null,null);Require(second.Online&&tracker.For(second).LiveConnectionId==201&&tracker.For(second).Candidate=="198.51.100.20:7777"&&tracker.For(second).LatestFailedAttemptId==0&&tracker.For(second).LatestProgress=="duplicate connection loser","Inbound duplicate loser replaced the outbound winner projection");view.Apply(new CoreEvent{kind=4,expected=peerTwo,peer=peerTwo,attempt=202,text="duplicate loser closed"});Require(second.Online,"Inbound duplicate loser disconnected the outbound winner");view.Apply(new CoreEvent{kind=4,expected=peerTwo,peer=peerTwo,attempt=201,text="remote EOF"});Require(!second.Online,"Outbound winner disconnect was not projected");
        var authoritative=new CoreEvent{kind=17,expected=peerTwo,peer=peerTwo,sessionEpoch=7,sessionRevision=10,connected=true,attempt=301,candidate="10.0.0.8:7777",source="Session manager",route="active direct",detail="inbound",text="Ready"};view.Apply(authoritative);tracker.Update(authoritative,second,"Ready","Verified",null);Require(second.Online&&second.WinningConnectionId==301&&tracker.For(second).LiveConnectionId==301,"authoritative session snapshot was not projected");view.Apply(new CoreEvent{kind=4,expected=peerTwo,peer=peerTwo,attempt=301,text="legacy delayed disconnect"});Require(second.Online,"legacy disconnect overrode authoritative snapshot state");view.Apply(new CoreEvent{kind=17,expected=peerTwo,peer=peerTwo,sessionEpoch=7,sessionRevision=9,connected=false,text="Offline"});Require(second.Online,"stale snapshot revision downgraded the current winner");var offlineSnapshot=new CoreEvent{kind=17,expected=peerTwo,peer=peerTwo,sessionEpoch=7,sessionRevision=11,connected=false,text="Retrying with backoff"};view.Apply(offlineSnapshot);tracker.Update(offlineSnapshot,second,offlineSnapshot.text,null,null);Require(!second.Online&&second.WinningConnectionId==0&&!tracker.For(second).HasLiveSession,"new authoritative disconnect snapshot was not projected");
        int conversations=view.Conversations.Count;view.Apply(new CoreEvent{kind=2,expected=newPeer,peer=wrongPeer,text="Peer identity changed"});Require(view.Conversations.Count==conversations&&same.Contact.peer==newPeer&&!Object.ReferenceEquals(view.FindByPeer(wrongPeer),same),"Wrong-identity fallback created or rebound a conversation before verification");
    }
    static void TestProfileAccountBinding(string root){
        Func<byte[],byte[]> identity=data=>data;string aPath=Path.Combine(root,"account-A"),bPath=Path.Combine(root,"account-B");
        var a=new ProfileAccountStore(aPath,identity,identity);a.SaveSession(1001,"account-a","localhost",7443,"pin-a","token-a");var loaded=new ProfileAccountStore(aPath,identity,identity).Load();Require(loaded.AccountId==1001&&loaded.Username=="account-a"&&loaded.SessionToken=="token-a","Protected profile account session did not survive reload");
        bool mismatch=false;try{a.SaveSession(2002,"account-b","localhost",7443,"pin-b","token-b");}catch(InvalidOperationException){mismatch=true;}Require(mismatch&&a.Load().AccountId==1001,"A profile silently changed to B account");
        var b=new ProfileAccountStore(bPath,identity,identity);b.SaveSession(2002,"account-b","localhost",7443,"pin-b","token-b");a.ClearSession();Require(a.Load().AccountId==1001&&!a.Load().HasSession,"Signing out removed the durable A account binding");Require(b.Load().AccountId==2002&&b.Load().SessionToken=="token-b","Signing out A altered B profile's session");
        string damagedPath=Path.Combine(root,"account-damaged");Directory.CreateDirectory(damagedPath);File.WriteAllText(Path.Combine(damagedPath,"account-link.dat"),"damaged");var damaged=new ProfileAccountStore(damagedPath,identity,identity);bool damagedRefused=false;try{damaged.SaveSession(3003,"account-c","localhost",7443,"pin-c","token-c");}catch(InvalidOperationException){damagedRefused=true;}Require(damaged.Exists&&damaged.Load()==null&&damagedRefused,"An unreadable account binding was mistaken for a new unlinked profile");
    }
    static void TestVoicePreferences(string root){
        Func<byte[],byte[]> identity=data=>data;string path=Path.Combine(root,"voice-preferences");
        var store=new VoicePreferenceStore(path,identity,identity);var value=new VoicePreferenceData{InputDeviceId=7,InputDeviceName="Test microphone",OutputDeviceId=8,OutputDeviceName="Test output",InputVolume=80,OutputVolume=125,AudioProcessingEnabled=false,NoiseSuppressionEnabled=false,AutomaticGainEnabled=true};store.Save(value);
        var loaded=store.Load();Require(loaded.InputDeviceId==7&&loaded.OutputDeviceId==8&&loaded.InputVolume==80&&loaded.OutputVolume==125&&!loaded.AudioProcessingEnabled&&!loaded.NoiseSuppressionEnabled&&loaded.AutomaticGainEnabled,"Voice preferences did not survive profile-local protected persistence");
        VoicePreferenceStore.ResolveDevices(loaded,new VoiceDevices{inputs=new[]{new VoiceDevice{id=-1,name="Windows default microphone"}},outputs=new[]{new VoiceDevice{id=-1,name="Windows default output"}}});
        Require(loaded.InputDeviceId==-1&&loaded.OutputDeviceId==-1,"Missing audio devices did not fall back safely to system defaults");
        Require(!File.ReadAllText(Path.Combine(path,"voice-preferences.dat")).Contains("call"),"Live call state leaked into persistent voice preferences");
        var other=new VoicePreferenceStore(Path.Combine(root,"voice-preferences-other"),identity,identity).Load();
        Require(other.AudioProcessingEnabled&&other.NoiseSuppressionEnabled&&other.AutomaticGainEnabled,"New profile did not retain default-on APM settings independently");
        string legacyPath=Path.Combine(root,"voice-preferences-legacy");Directory.CreateDirectory(legacyPath);
        File.WriteAllText(Path.Combine(legacyPath,"voice-preferences.dat"),"{\"Version\":1,\"InputDeviceId\":-1,\"OutputDeviceId\":-1,\"InputDeviceName\":\"Windows default microphone\",\"OutputDeviceName\":\"Windows default output\",\"InputVolume\":100,\"OutputVolume\":100}");
        var legacy=new VoicePreferenceStore(legacyPath,identity,identity).Load();
        Require(legacy.AudioProcessingEnabled&&legacy.NoiseSuppressionEnabled&&legacy.AutomaticGainEnabled,"Existing voice preferences without APM fields lost default-on processing");
    }
