            var profileB=profiles.Create("Profile B");b=new CoreAdapter();bv=new ChatViewModel();Action pumpB=()=>{foreach(var e in b.Poll()){if(e.kind==8)throw new Exception(e.text);bv.Apply(e);}};b.Start(profiles.ProfilePath(profileB.Id),29532,"");Until(()=>bv.Listening,pumpB,"profile B start");string firstBId=bv.OwnId;Require(firstBId!=aId,"Profiles A and B shared a Peer ID");Require(bv.Conversations.Count==0,"Profile A trust or history appeared in B");b.Dispose();
            profiles.Select(profileA.Id);a=new CoreAdapter();av=new ChatViewModel();pumpA=()=>{foreach(var e in a.Poll()){if(e.kind==8)throw new Exception(e.text);av.Apply(e);}};a.Start(profiles.ProfilePath(profileA.Id),29531,"");Until(()=>av.Listening,pumpA,"switch B to A");Require(av.OwnId==aId&&av.FindByPeer(bId)!=null&&av.Get(bId).Contact.verified,"Switching A-B-A did not restore A state");a.Dispose();
            profiles.Select(profileB.Id);string backup=Path.Combine(root,"backup-B");var backupRequest=profiles.CreateMaintenanceRequest(ProfileMaintenanceAction.Backup,profileB.Id,backup);profiles.ExecuteMaintenance(backupRequest,(oldPath,newPath)=>"");profiles.CompleteMaintenanceRequest(backupRequest);string resetRoot=Path.Combine(root,"reset-B");var resetRequest=profiles.CreateMaintenanceRequest(ProfileMaintenanceAction.Reset,profileB.Id,resetRoot);profiles.ExecuteMaintenance(resetRequest,(oldPath,newPath)=>{using(var maintenance=new CoreAdapter()){maintenance.RebuildProfileIdentity(oldPath,newPath);return maintenance.ProfilePeerId(newPath);}});profiles.CompleteMaintenanceRequest(resetRequest);b=new CoreAdapter();bv=new ChatViewModel();pumpB=()=>{foreach(var e in b.Poll()){if(e.kind==8)throw new Exception(e.text);bv.Apply(e);}};b.Start(profiles.ProfilePath(profileB.Id),29532,"");Until(()=>bv.Listening,pumpB,"reset B");Require(bv.OwnId==firstBId,"Reset B did not preserve the existing Peer ID");b.Dispose();
            string restoreSafety=Path.Combine(root,"before-restore-B");var restoreRequest=profiles.CreateMaintenanceRequest(ProfileMaintenanceAction.Restore,profileB.Id,restoreSafety,backup);profiles.ExecuteMaintenance(restoreRequest,(oldPath,newPath)=>"");profiles.CompleteMaintenanceRequest(restoreRequest);b=new CoreAdapter();bv=new ChatViewModel();pumpB=()=>{foreach(var e in b.Poll()){if(e.kind==8)throw new Exception(e.text);bv.Apply(e);}};b.Start(profiles.ProfilePath(profileB.Id),29532,"");Until(()=>bv.Listening,pumpB,"restore B");Require(bv.OwnId==firstBId,"Restore B did not restore its exact identity");b.Dispose();
            profiles.Select(profileA.Id);a=new CoreAdapter();av=new ChatViewModel();pumpA=()=>{foreach(var e in a.Poll()){if(e.kind==8)throw new Exception(e.text);av.Apply(e);}};a.Start(profiles.ProfilePath(profileA.Id),29531,"");Until(()=>av.Listening,pumpA,"A after B reset/restore");Require(av.OwnId==aId,"Reset or restore B altered A");a.History(bId,long.MaxValue);Until(()=>av.Get(bId).Messages.Count==2,pumpA,"A history after B restore");
            var replacement=new CoreAdapter();var replacementView=new ChatViewModel();var verifier=new CoreAdapter();var verifierView=new ChatViewModel();try{replacement.Start(Path.Combine(root,"replacement-device"),29533,"Replacement");verifier.Start(Path.Combine(root,"identity-verifier"),29534,"Verifier");Action pumpReplacement=()=>{foreach(var e in replacement.Poll()){replacementView.Apply(e);if(e.kind==2)replacement.Approve(e.peer,true);}foreach(var e in verifier.Poll())verifierView.Apply(e);};Until(()=>replacementView.Listening&&verifierView.Listening,pumpReplacement,"replacement identity peers");int prompts=0;string warning="";verifier.Connect("127.0.0.1",replacementView.Port,bId);Action pumpIdentityChange=()=>{foreach(var e in verifier.Poll()){verifierView.Apply(e);if(e.kind==2){prompts++;warning=e.text;}}foreach(var e in replacement.Poll()){replacementView.Apply(e);if(e.kind==2)replacement.Approve(e.peer,true);}};Until(()=>prompts==1,pumpIdentityChange,"replacement identity verification");var duplicateWindow=Stopwatch.StartNew();while(duplicateWindow.ElapsedMilliseconds<500){pumpIdentityChange();Thread.Sleep(20);}Require(prompts==1,"Replacement identity produced more than one verification prompt");Require(warning.Contains(bId)&&warning.Contains(replacementView.OwnId),"Identity warning did not show expected and presented Peer IDs");verifier.Approve(replacementView.OwnId,false);}finally{replacement.Dispose();verifier.Dispose();}
            Console.WriteLine("PASS: adapter, encrypted history/trust, legacy migration, isolated A/B switching/reset/restore, and one explicit expected/presented replacement-identity verification.");
        }finally{a.Dispose();b.Dispose();}return 0;
    }catch(Exception e){Console.Error.WriteLine("FAIL: "+e);return 1;}}
